<?php

declare(strict_types=1);

use App\Domain\Invoicing\ForeignSale;
use App\Domain\Invoicing\InvoicePdf;
use App\Models\Company;
use App\Models\Invoice;
use App\Support\Peppol\PeppolDocumentRules;
use App\Support\Peppol\PeppolIdentifier;
use App\Support\Peppol\UblInvoiceParser;
use App\Support\Peppol\UblInvoiceWriter;
use Tests\Support\PeppolFixtures;

/*
 * Golden files: tests/Fixtures/peppol/*.xml were generated by this test
 * (PEPPOL_GOLDEN=write) and validated with the official Peppol BIS Billing
 * 3.0 Schematron (CEN-EN16931-UBL.sch and PEPPOL-EN16931-UBL.sch, May 2026
 * release) by scripts/peppol-validate.sh, with no failed assertions
 * (ADR-050). Here every document is compared with its golden file and
 * checked by the curated rule set (PeppolDocumentRules) and the reader.
 */
beforeEach(function () {
    [$this->owner, $this->company] = PeppolFixtures::company();
    $this->seller = PeppolIdentifier::forOrganisationNumber($this->company->org_number);
    $this->buyer = PeppolIdentifier::make('0007', PeppolFixtures::BUYER_ORG);
});

function peppolXml(Invoice $invoice, Company $company, ?string $pdf = '%PDF-1.4 syntetisk testfil'): string
{
    return app(UblInvoiceWriter::class)->write($invoice, $company, test()->seller, test()->buyer, $pdf);
}

function peppolGolden(string $name, string $xml): void
{
    $path = base_path("tests/Fixtures/peppol/{$name}.xml");

    if (getenv('PEPPOL_GOLDEN') === 'write') {
        @mkdir(dirname($path), 0755, true);
        file_put_contents($path, $xml);
    }

    expect(PeppolDocumentRules::check($xml))->toBe([])
        ->and($xml)->toBe((string) file_get_contents($path));
}

it('writes a domestic invoice with 25, 12 and 6 percent, a discount, öresavrundning and Swedish payment details', function () {
    $customer = PeppolFixtures::customer($this->owner, $this->company);
    $invoice = PeppolFixtures::invoice($this->owner, $this->company, $customer, [
        ['description' => 'Konsulttimmar', 'quantity' => '7,5', 'unit' => 'tim', 'price' => '950', 'vat_rate' => 2500],
        ['description' => 'Lättöl', 'quantity' => '12', 'unit' => 'st', 'price' => '24,90', 'vat_rate' => 1200, 'discount' => '10'],
        ['description' => 'Facklitteratur', 'quantity' => '1', 'unit' => 'st', 'price' => '199,33', 'vat_rate' => 600],
    ]);
    $xml = peppolXml($invoice, $this->company);

    expect($invoice->rounding_ore->ore)->not->toBe(0);
    peppolGolden('inrikes-25-12-6', $xml);

    $read = app(UblInvoiceParser::class)->parse($xml);
    expect($read->payableOre)->toBe($invoice->total_ore->ore)
        ->and($read->vatOre)->toBe($invoice->vat_ore->ore)
        ->and($read->ocr)->toBe($invoice->ocr)
        ->and($read->bankgiro)->toBe('1234567')
        ->and($read->supplierOrgNumber)->toBe(PeppolFixtures::SELLER_ORG)
        ->and($read->embeddedDocument['contents'] ?? null)->toBe('%PDF-1.4 syntetisk testfil')
        ->and(array_keys($read->vatBreakdown))->toBe([25, 12, 6]);
});

it('writes reverse charge for construction services as category AE', function () {
    $customer = PeppolFixtures::customer($this->owner, $this->company, ['reverse_charge_construction' => true]);
    $invoice = PeppolFixtures::invoice($this->owner, $this->company, $customer, [
        ['description' => 'Takarbete', 'quantity' => '40', 'unit' => 'tim', 'price' => '600', 'vat_rate' => 2500],
    ], ['reverse_charge' => true]);

    expect($invoice->vat_ore->ore)->toBe(0);
    $xml = peppolXml($invoice, $this->company);

    expect($xml)->toContain('<cbc:ID>AE</cbc:ID>')->toContain('VATEX-EU-AE');
    peppolGolden('omvand-byggtjanst', $xml);
});

it('writes EU goods as K with the country delivered to, and EU services as AE', function () {
    $german = PeppolFixtures::customer($this->owner, $this->company, [
        'name' => 'Muster GmbH', 'org_number' => null, 'vat_number' => 'DE123456789', 'country' => 'DE', 'city' => 'Berlin', 'postal_code' => '10115', 'address_line1' => 'Teststraße 1',
        'foreign_sale' => ForeignSale::EuGoods->value,
    ]);
    $goods = PeppolFixtures::invoice($this->owner, $this->company, $german, [
        ['description' => 'Reservdelar', 'quantity' => '3', 'unit' => 'st', 'price' => '1 200', 'vat_rate' => 2500],
    ]);
    $services = PeppolFixtures::invoice($this->owner, $this->company, $german, [
        ['description' => 'Konsultarbete', 'quantity' => '10', 'unit' => 'tim', 'price' => '1 000', 'vat_rate' => 2500],
    ], ['foreign_sale' => ForeignSale::EuServices->value]);
    $this->buyer = PeppolIdentifier::make('9930', 'DE123456789');

    peppolGolden('eu-varor', peppolXml($goods, $this->company));
    peppolGolden('eu-tjanster', peppolXml($services, $this->company));
});

it('writes an export as G and exempt rows as E with the exemption text', function () {
    $american = PeppolFixtures::customer($this->owner, $this->company, [
        'name' => 'Example Inc', 'org_number' => null, 'vat_number' => null, 'country' => 'US', 'city' => 'Boston', 'postal_code' => '02101',
        'foreign_sale' => ForeignSale::ExportGoods->value,
    ]);
    $export = PeppolFixtures::invoice($this->owner, $this->company, $american, [
        ['description' => 'Maskindel', 'quantity' => '2', 'unit' => 'st', 'price' => '5 000', 'vat_rate' => 2500],
    ]);
    $this->buyer = PeppolIdentifier::make('0088', '7300009000005') ?? throw new LogicException('GLN');
    peppolGolden('export', peppolXml($export, $this->company));

    $this->buyer = PeppolIdentifier::make('0007', PeppolFixtures::BUYER_ORG);
    $customer = PeppolFixtures::customer($this->owner, $this->company);
    $mixed = PeppolFixtures::invoice($this->owner, $this->company, $customer, [
        ['description' => 'Kursavgift', 'quantity' => '1', 'unit' => 'st', 'price' => '2 000', 'vat_rate' => 0, 'vat_exemption' => 'EDUCATION'],
        ['description' => 'Kurslitteratur', 'quantity' => '1', 'unit' => 'st', 'price' => '300', 'vat_rate' => 600],
    ]);
    $xml = peppolXml($mixed, $this->company);

    expect($xml)->toContain('10 kap. 15–18 §§');
    peppolGolden('momsfri-rad', $xml);
});

it('writes a credit note with positive amounts that refers to the invoice it credits', function () {
    $customer = PeppolFixtures::customer($this->owner, $this->company);
    $invoice = PeppolFixtures::invoice($this->owner, $this->company, $customer, [
        ['description' => 'Konsulttimmar', 'quantity' => '3', 'unit' => 'tim', 'price' => '950,50', 'vat_rate' => 2500],
    ]);
    $credit = PeppolFixtures::credit($this->owner, $invoice);
    $xml = peppolXml($credit, $this->company);

    expect($credit->total_ore->ore)->toBeLessThan(0)
        ->and($xml)->toContain('<CreditNote')
        ->toContain('<cbc:CreditNoteTypeCode>381</cbc:CreditNoteTypeCode>')
        ->toContain("<cbc:ID>{$invoice->number}</cbc:ID>")
        ->not->toContain('PayableAmount currencyID="SEK">-');
    peppolGolden('kreditnota', $xml);

    $read = app(UblInvoiceParser::class)->parse($xml);
    expect($read->isCreditNote)->toBeTrue()
        ->and($read->payableOre)->toBe(-$credit->total_ore->ore);
});

it('writes an invoice in euro with the VAT also in kronor', function () {
    $customer = PeppolFixtures::customer($this->owner, $this->company, ['currency' => 'EUR']);
    $invoice = PeppolFixtures::invoice($this->owner, $this->company, $customer, [
        ['description' => 'Konsultarbete', 'quantity' => '1', 'unit' => 'st', 'price' => '33,33', 'vat_rate' => 2500],
        ['description' => 'Konsultarbete', 'quantity' => '2', 'unit' => 'st', 'price' => '33,33', 'vat_rate' => 2500],
    ], ['currency' => 'EUR', 'exchange_rate' => '11,234567']);
    $xml = peppolXml($invoice, $this->company);

    expect($invoice->isForeign())->toBeTrue()
        ->and($xml)->toContain('<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode>')
        ->toContain('<cbc:TaxCurrencyCode>SEK</cbc:TaxCurrencyCode>')
        ->toContain('<cbc:TaxAmount currencyID="SEK">'.UblInvoiceWriter::minor($invoice->vat_ore->ore).'</cbc:TaxAmount>');
    peppolGolden('euro', $xml);
});

it('embeds the real invoice PDF', function () {
    $customer = PeppolFixtures::customer($this->owner, $this->company);
    $invoice = PeppolFixtures::invoice($this->owner, $this->company, $customer, [
        ['description' => 'Arbete', 'quantity' => '1', 'unit' => 'st', 'price' => '1 000', 'vat_rate' => 2500],
    ]);
    $xml = peppolXml($invoice, $this->company, InvoicePdf::render($invoice));
    $read = app(UblInvoiceParser::class)->parse($xml);

    expect(PeppolDocumentRules::check($xml))->toBe([])
        ->and(str_starts_with((string) ($read->embeddedDocument['contents'] ?? ''), '%PDF'))->toBeTrue()
        ->and($read->embeddedDocument['filename'] ?? null)->toBe("Faktura-{$invoice->number}.pdf");
});

it('refuses invoices Peppol cannot carry', function () {
    $customer = PeppolFixtures::customer($this->owner, $this->company);
    $invoice = PeppolFixtures::invoice($this->owner, $this->company, $customer, [
        ['description' => 'Arbete', 'quantity' => '1', 'unit' => 'st', 'price' => '1 000', 'vat_rate' => 2500],
    ]);

    expect(UblInvoiceWriter::unsupportedReason($invoice, $this->company))->toBeNull();

    $this->company->forceFill(['vat_number' => null])->save();
    expect(UblInvoiceWriter::unsupportedReason($invoice, $this->company))->toContain('momsregistreringsnummer');
});

it('maps Swedish units to UN/ECE Recommendation 20', function () {
    expect(UblInvoiceWriter::unitCode('st'))->toBe('H87')
        ->and(UblInvoiceWriter::unitCode('tim'))->toBe('HUR')
        ->and(UblInvoiceWriter::unitCode('KGM'))->toBe('KGM')
        ->and(UblInvoiceWriter::unitCode('påse'))->toBe('C62')
        ->and(UblInvoiceWriter::minor(-5))->toBe('-0.05')
        ->and(UblInvoiceWriter::minor(123456))->toBe('1234.56');
});

it('reads and validates participant identifiers', function () {
    expect(PeppolIdentifier::tryFrom('0007:559999-6013')?->toString())->toBe('0007:5599996013')
        ->and(PeppolIdentifier::tryFrom('iso6523-actorid-upis::0007:5599996013')?->toString())->toBe('0007:5599996013')
        ->and(PeppolIdentifier::tryFrom('0007:5599000007'))->toBeNull()
        ->and(PeppolIdentifier::tryFrom('0088:7300009000005')?->value)->toBe('7300009000005')
        ->and(PeppolIdentifier::tryFrom('0088:7300009000006'))->toBeNull()
        ->and(PeppolIdentifier::tryFrom('9955:SE559999601301'))->toBeNull()
        ->and(PeppolIdentifier::tryFrom('9930:DE123456789')?->urn())->toBe('iso6523-actorid-upis::9930:DE123456789')
        ->and(PeppolIdentifier::tryFrom('5599996013'))->toBeNull();
});

it('catches documents that break the rules', function () {
    $xml = (string) file_get_contents(base_path('tests/Fixtures/peppol/inrikes-25-12-6.xml'));
    $broken = (string) preg_replace('#<cbc:BuyerReference>.*</cbc:BuyerReference>#', '', str_replace('<cbc:PayableAmount currencyID="SEK">9419.00', '<cbc:PayableAmount currencyID="SEK">9500.00', $xml));
    $broken = str_replace('<cbc:ID>1234567</cbc:ID>', '<cbc:ID>123-4567</cbc:ID>', $broken);
    $rules = array_map(fn (string $error): string => (string) strtok($error, ':'), PeppolDocumentRules::check($broken));

    expect($rules)->toContain('BR-CO-16')->toContain('PEPPOL-EN16931-R003')->toContain('SE-R-009')
        ->and(PeppolDocumentRules::check('<!DOCTYPE x><x/>'))->toBe(['XML: the document cannot be read.']);
});

it('writes the intermediary\'s sale in triangulation as reverse charge with the article 141 text', function () {
    $german = PeppolFixtures::customer($this->owner, $this->company, [
        'name' => 'Muster GmbH', 'org_number' => null, 'vat_number' => 'DE123456789', 'country' => 'DE', 'city' => 'Berlin', 'postal_code' => '10115', 'address_line1' => 'Teststraße 1',
        'foreign_sale' => ForeignSale::EuTriangular->value,
    ]);
    $invoice = PeppolFixtures::invoice($this->owner, $this->company, $german, [
        ['description' => 'Maskiner', 'quantity' => '1', 'unit' => 'st', 'price' => '10 000', 'vat_rate' => 2500],
    ]);
    $this->buyer = PeppolIdentifier::make('9930', 'DE123456789');
    $xml = peppolXml($invoice, $this->company);

    expect($xml)->toContain('<cbc:ID>AE</cbc:ID>')->toContain('VATEX-EU-AE')->toContain('artikel 141')->not->toContain('VATEX-EU-IC')
        ->and(PeppolDocumentRules::check($xml))->toBe([]);
});

it('refuses an invoice without VAT from an unregistered seller that gives no reason', function () {
    $customer = PeppolFixtures::customer($this->owner, $this->company);
    $invoice = PeppolFixtures::invoice($this->owner, $this->company, $customer, [
        ['description' => 'Arbete', 'quantity' => '1', 'unit' => 'st', 'price' => '1 000', 'vat_rate' => 0, 'vat_exemption' => 'OTHER'],
    ]);
    $this->company->forceFill(['vat_number' => null, 'vat_exemption' => null])->save();

    expect(UblInvoiceWriter::unsupportedReason($invoice, $this->company))->toContain('utan moms');

    $this->company->forceFill(['vat_exemption' => 'SMALL_BUSINESS'])->save();
    expect(UblInvoiceWriter::unsupportedReason($invoice, $this->company))->toBeNull();
});
